-- =====================================================================================================
-- Bedo Chat: bring the live database up to date in ONE run from the Supabase SQL Editor (D-35, D-36).
-- GENERATED by scripts/build-owner-sql.mjs from supabase/migrations: do not edit by hand.
--
-- For the Bedo Chat project, whose migrations 1-6 were applied by hand and whose runtime login bedo_api already
-- exists (created in the SQL Editor, member of bedo_runtime). It applies, exactly as delivered and in order:
--    7  20261006120000_d35_admin_password_owner_sql
--    8  20261006180000_phase3_3_single_site
--    9  20261009120000_phase3_3_private_realtime
--   10  20261010120000_phase4_media
--   11  20261011120000_phase5_groups
--   12  20261012120000_phase6_channels
--   13  20261013120000_phase7_notifications
--   14  20261014120000_phase8_search
--   15  20261015120000_phase9_hardening
--   16  20261016120000_phase10_admin
--   17  20261017120000_phase13_launch
-- then sets the two limits on bedo_api, checks everything and records the 11 migrations.
--
-- How: SQL Editor -> New query -> paste this whole file -> Run ONCE (role: postgres). No values to change.
-- One request = one transaction: if any check or statement fails, NOTHING is kept and the message says why.
-- Expected result: a list of checks, every one "ok".
-- =====================================================================================================

-- Part 1: safety checks (change nothing) ------------------------------------------------------------------
do $preflight$
begin
  if current_user <> 'postgres' then
    raise exception 'Stopped: run this as postgres, not %', current_user;
  end if;
  if to_regclass('app_meta.schema_migrations') is null then
    raise exception 'Stopped: app_meta.schema_migrations does not exist';
  end if;
  -- Exactly migrations 1-6 (through Phase 3.2) with the delivered checksums.
  if (select count(*) from app_meta.schema_migrations) <> 6
     or (select count(*) from app_meta.schema_migrations m
         join (values
           ('20261004000000', 'baseline',
            'b5e5d3cdea7f92cf9687530e892d01efaaf9c2c22b3399d684f625af8c4dd1d9'),
           ('20261004120000', 'phase2_accounts',
            '895f083bf26597405b30c2e04e6aa119747c430b394eece7804d74a5a42470af'),
           ('20261004130000', 'd24_phone_list_removal',
            'd681767b521e38e614c813eb8ac537d08b056c0a50d32d49c9e767b0d2772e1f'),
           ('20261004135000', 'phase3_1_admin_bootstrap',
            '10f385bccdf962c9c309e5b43136931491adac58c4d6bb51cffec563c0fc4f28'),
           ('20261004140000', 'phase3_messaging',
            'd973c91631e161e11d8faf7fbb8a0b18a190bd2e804e1df7b3679b8345cd95ac'),
           ('20261005120000', 'phase3_2_admin_password',
            'af7c5f0af73f01b691c16cc721d72254958141e94a20d59c3dcfeff0d692478c')
         ) as e(version, name, checksum)
           on e.version = m.version and e.name = m.name and e.checksum = m.checksum) <> 6 then
    raise exception 'Stopped: app_meta.schema_migrations does not hold exactly migrations 1-6 with the delivered checksums';
  end if;
  if not exists (select 1 from pg_constraint
                 where conrelid = 'app.admin_accounts'::regclass and conname = 'admin_accounts_password_hash_check'
                   and pg_get_constraintdef(oid) not like '%2a%') then
    raise exception 'Stopped: the Phase 3.2 password_hash check is missing or already changed';
  end if;
  if exists (select 1 from pg_tables where schemaname = 'app'
             and tablename in ('ephemeral', 'rate_counters', 'rate_events', 'presence_devices', 'maintenance_runs', 'files')) then
    raise exception 'Stopped: a table of a later release already exists';
  end if;
  if (select tableowner from pg_tables where schemaname = 'app' and tablename = 'users') <> 'postgres'
     or (select tableowner from pg_tables where schemaname = 'app' and tablename = 'admin_accounts') <> 'postgres' then
    raise exception 'Stopped: the app tables are not owned by postgres';
  end if;
  if not exists (select 1 from pg_roles where rolname = 'bedo_api' and rolcanlogin) then
    raise exception 'Stopped: the login bedo_api does not exist (create it first: docs/DEPLOYMENT.md, section 0)';
  end if;
  if not pg_has_role('bedo_api', 'bedo_runtime', 'member') then
    raise exception 'Stopped: bedo_api is not a member of bedo_runtime';
  end if;
  if to_regclass('realtime.messages') is null then
    raise exception 'Stopped: realtime.messages does not exist (this must be the Supabase project)';
  end if;
  if to_regclass('storage.buckets') is null then
    raise exception 'Stopped: storage.buckets does not exist (this must be the Supabase project)';
  end if;
  -- A device's realtime token is a Supabase token for the role "authenticated". It must grant nothing except
  -- receiving on its own channel, so nothing else may be open to that role (or to anon).
  if exists (select 1 from pg_policies where schemaname = 'realtime' and tablename = 'messages'
             and policyname <> 'bedo_device_receives_own_channel') then
    raise exception 'Stopped: realtime.messages already has other policies (%): delete them first (they would let other tokens read private channels)',
      (select string_agg(policyname, ', ') from pg_policies where schemaname = 'realtime' and tablename = 'messages'
       and policyname <> 'bedo_device_receives_own_channel');
  end if;
  if exists (select 1 from information_schema.role_table_grants
             where grantee in ('anon', 'authenticated') and table_schema in ('app', 'app_meta', 'audit')) then
    raise exception 'Stopped: the roles anon/authenticated can reach Bedo Chat tables';
  end if;
  if to_regclass('storage.objects') is not null
     and exists (select 1 from pg_policies where schemaname = 'storage'
                 and (roles && array['anon', 'authenticated', 'public']::name[])) then
    raise exception 'Stopped: Supabase Storage has policies for anon/authenticated (Bedo Chat uses none): delete them first';
  end if;
end
$preflight$;

-- Part 2: supabase/migrations/20261006120000_d35_admin_password_owner_sql.sql, exactly as delivered -------------
-- Bedo Chat - D-35: admin password set by the owner from the SQL editor (docs/owner-sql/set-super-admin.sql).
--
-- The database cannot produce the API's Argon2id hash, so the owner script stores a temporary bcrypt hash
-- (pgcrypto crypt(), cost 12) of the password's SHA-256 (base64). The API accepts it once and, on the first
-- successful sign-in, replaces it with its own Argon2id hash after checking the full password rules (D-34).
-- Only that exact bcrypt form is allowed besides Argon2id; nothing else about admin accounts changes.

alter table app.admin_accounts drop constraint admin_accounts_password_hash_check;
alter table app.admin_accounts add constraint admin_accounts_password_hash_check check (
  password_hash is null
  or (password_hash like '$argon2id$%' and length(password_hash) <= 512)
  or password_hash ~ '^\$2a\$12\$[./A-Za-z0-9]{53}$'
);

comment on column app.admin_accounts.password_hash is
  'Argon2id hash (PHC string) of the admin password (D-34), or until the first sign-in a bcrypt hash written by the owner SQL script (D-35). NULL until a password is set.';
-- End of the delivered migration file 20261006120000 ------------------------------------------------------------

-- Part 3: supabase/migrations/20261006180000_phase3_3_single_site.sql, exactly as delivered ---------------------
-- Bedo Chat - Phase 3.3 (D-36): one Netlify site, no separate API host, no Redis.
--
-- The API now runs inside the website's server functions, which keep no state between requests. What Redis
-- held moves here, all short-lived and owned by the runtime role:
--   app.ephemeral        pending sign-ins (2-Step, admin), authenticator setup secrets (encrypted), photo uploads
--   app.rate_counters    fixed-window attempt counters (sign-in, setup tokens, messaging limits, ...)
--   app.rate_events      sliding-window events for the one-time-code limits (per number, per address)
--   app.presence_devices which signed-in devices are online right now (heartbeat every 25 s, 60 s each, P-18)
--   app.maintenance_runs when the hourly housekeeping last ran (it runs from ordinary requests)
-- Expired rows are ignored by every read and removed by the hourly housekeeping. Nothing here is audit
-- history; the audit tables are unchanged.

create table app.ephemeral (
  key        text primary key check (length(key) between 1 and 300),
  value      text not null check (length(value) <= 16384),
  expires_at timestamptz not null
);
create index ephemeral_expires_idx on app.ephemeral (expires_at);
comment on table app.ephemeral is
  'Short-lived server state with an expiry (D-36): pending sign-ins, setup secrets (encrypted), upload tickets. Never audit history.';

create table app.rate_counters (
  key        text primary key check (length(key) between 1 and 300),
  count      integer not null check (count >= 0),
  expires_at timestamptz not null
);
create index rate_counters_expires_idx on app.rate_counters (expires_at);
comment on table app.rate_counters is 'Fixed-window rate-limit counters (D-36). A row past expires_at counts as zero.';

create table app.rate_events (
  bucket text not null check (length(bucket) between 1 and 300),
  at     timestamptz not null
);
create index rate_events_bucket_at_idx on app.rate_events (bucket, at);
comment on table app.rate_events is 'Sliding-window events for the one-time-code limits (D-36), one row per code sent.';

create table app.presence_devices (
  user_id    uuid not null references app.users (id),
  session_id uuid not null,
  expires_at timestamptz not null,
  primary key (user_id, session_id)
);
create index presence_devices_expires_idx on app.presence_devices (expires_at);
comment on table app.presence_devices is
  'Signed-in devices that sent a heartbeat in the last 60 seconds (P-18, D-36). A user is online while one is unexpired.';

create table app.maintenance_runs (
  name        text primary key check (length(name) between 1 and 100),
  last_run_at timestamptz not null
);
comment on table app.maintenance_runs is 'When each hourly housekeeping task last ran (D-36).';

grant select, insert, update, delete on app.ephemeral, app.rate_counters, app.rate_events, app.presence_devices to bedo_runtime;
grant select, insert, update on app.maintenance_runs to bedo_runtime;
-- End of the delivered migration file 20261006180000 ------------------------------------------------------------

-- Part 4: supabase/migrations/20261009120000_phase3_3_private_realtime.sql, exactly as delivered ----------------
-- Bedo Chat - D-36: private realtime channels (Supabase Realtime Authorization).
--
-- Each signed-in device receives realtime signals on its own channel. The API gives the device a short-lived token
-- (a JWT signed with the project's JWT secret, role "authenticated") whose claim "bedo_topic" names that one channel.
-- This policy is the only permission on realtime.messages for devices: a device may RECEIVE broadcasts on the channel
-- its token names, and nothing else. There is no insert policy, so no device can send (or fake) a signal; there is no
-- presence policy, so devices cannot see who else listens. The API sends with the service key, which bypasses
-- policies. With "Allow public access" turned off in the Realtime settings, every channel needs such a token.
--
-- How Supabase checks it: when a device joins a channel, Realtime sets realtime.topic (the channel), the device's JWT
-- claims and its role, then checks whether a broadcast row for that channel would be visible under these policies.
--
-- realtime.messages exists only on Supabase; on any other Postgres (local development, tests) nothing is created.

do $private_realtime$
begin
  if to_regclass('realtime.messages') is null or to_regprocedure('realtime.topic()') is null then
    raise notice 'realtime.messages not found (not a Supabase database): no realtime policy created';
    return;
  end if;
  if not exists (select 1 from pg_roles where rolname = 'authenticated') then
    raise exception 'Stopped: the role "authenticated" does not exist';
  end if;

  execute 'drop policy if exists bedo_device_receives_own_channel on realtime.messages';
  execute $policy$
    create policy bedo_device_receives_own_channel on realtime.messages
      as permissive
      for select
      to authenticated
      using (
        realtime.messages.extension = 'broadcast'
        and realtime.messages.topic = (select realtime.topic())
        and (select realtime.topic()) = (
          select nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'bedo_topic'
        )
      )
  $policy$;
end
$private_realtime$;
-- End of the delivered migration file 20261009120000 ------------------------------------------------------------

-- Part 5: supabase/migrations/20261010120000_phase4_media.sql, exactly as delivered -----------------------------
-- Bedo Chat - Phase 4: media, stickers, GIFs and reactions (D-38).
--
-- Files. A browser asks the API for an upload slot (kind, type, size, the chat), uploads straight to the private
-- bucket "chat-media" with a one-time signed URL, then sends the message. Before the message exists the API reads
-- the stored object back (real size, real type from its first bytes); only then is the file marked ready and
-- attached. A file is never replaced (signed uploads cannot overwrite) and a ready file never changes or goes away:
-- forwarding a message references the same file, and deleting a message only hides it (D-38: the object stays in
-- the private bucket, locked, as part of the permanent history; no user can download it any more). Upload slots
-- that were never used are removed by the hourly housekeeping after a day.
--
-- Stickers are packs that Super Admins upload (O-10), stored in the public bucket "stickers". GIFs come from GIPHY
-- through the API (O-09): sending one copies it into "chat-media" once, and later sends of the same GIF reuse it.
-- Reactions: one emoji per person per message, from a fixed set.
--
-- Storage buckets exist only on Supabase; on any other Postgres (local development, tests) they are skipped.

-------------------------------------------------------------------------------------------------------
-- Files
-------------------------------------------------------------------------------------------------------
create table app.files (
  id              uuid primary key default app.uuid_v7(),
  -- Who asked for the upload slot (for a GIF: who first sent it).
  owner_id        uuid not null references app.users (id),
  kind            text not null check (kind in ('photo', 'video', 'audio', 'voice', 'video_note', 'file', 'gif')),
  -- For photos, videos, audio, voice and video messages: the type detected from the stored bytes.
  mime_type       text not null check (mime_type ~ '^[a-z0-9.+-]+/[a-z0-9.+-]+$' and length(mime_type) <= 100),
  size_bytes      bigint not null check (size_bytes between 1 and 52428800),
  file_name       text check (file_name is null or char_length(file_name) between 1 and 255),
  object_path     text not null unique check (object_path ~ '^[a-z_]+/[0-9a-f-]{36}(\.[a-z0-9]{1,8})?$'),
  thumbnail_path  text unique check (thumbnail_path is null or thumbnail_path ~ '^thumbs/[0-9a-f-]{36}\.(jpg|webp)$'),
  width           integer check (width is null or width between 1 and 20000),
  height          integer check (height is null or height between 1 and 20000),
  duration_ms     integer check (duration_ms is null or duration_ms between 0 and 86400000),
  -- Voice messages: up to 100 bars, each 0-100.
  waveform        smallint[] check (waveform is null or (cardinality(waveform) between 1 and 100 and 0 <= all (waveform) and 100 >= all (waveform))),
  status          text not null default 'pending' check (status in ('pending', 'ready')),
  created_at      timestamptz not null default now(),
  ready_at        timestamptz,
  constraint files_ready_at check ((status = 'ready') = (ready_at is not null))
);
create index files_pending_idx on app.files (created_at) where status = 'pending';
comment on table app.files is
  'Files in chats (Phase 4). Objects live in the private bucket chat-media; ready files never change or go away (D-38).';

-- A ready file never changes and is never removed; only an unused upload slot (pending) may be removed or become ready.
create function app.files_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'DELETE' then
    if old.status = 'ready' then
      raise exception 'file % is part of the history and cannot be removed', old.id using errcode = 'check_violation';
    end if;
    return old;
  end if;
  if old.status = 'ready'
     or new.id <> old.id or new.owner_id <> old.owner_id or new.kind <> old.kind or new.object_path <> old.object_path
     or new.thumbnail_path is distinct from old.thumbnail_path and new.thumbnail_path is not null
     or new.created_at <> old.created_at then
    raise exception 'file % cannot change this way', old.id using errcode = 'check_violation';
  end if;
  return new;
end;
$$;
create trigger files_guard before update or delete on app.files
  for each row execute function app.files_guard();
create trigger files_no_truncate before truncate on app.files
  for each statement execute function app.forbid_mutation();

-------------------------------------------------------------------------------------------------------
-- Stickers (O-10): packs uploaded by Super Admins
-------------------------------------------------------------------------------------------------------
create table app.sticker_packs (
  id           uuid primary key default app.uuid_v7(),
  name         text not null check (char_length(name) between 1 and 64),
  created_by   uuid references app.admin_accounts (id),
  created_at   timestamptz not null default now(),
  -- Archived packs are not offered any more; stickers already sent keep showing.
  archived_at  timestamptz
);

create table app.stickers (
  id           uuid primary key default app.uuid_v7(),
  pack_id      uuid not null references app.sticker_packs (id),
  emoji        text not null check (char_length(emoji) between 1 and 16),
  object_path  text not null unique check (object_path ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}\.(png|webp)$'),
  mime_type    text not null check (mime_type in ('image/png', 'image/webp')),
  width        integer not null check (width between 1 and 1024),
  height       integer not null check (height between 1 and 1024),
  position     integer not null default 0,
  created_at   timestamptz not null default now(),
  removed_at   timestamptz
);
create index stickers_pack_idx on app.stickers (pack_id, position);

-- Stickers are referenced by messages: never removed, only taken out of the pack.
create trigger stickers_no_delete before delete on app.stickers
  for each row execute function app.forbid_mutation();
create trigger sticker_packs_no_delete before delete on app.sticker_packs
  for each row execute function app.forbid_mutation();

-------------------------------------------------------------------------------------------------------
-- GIFs (O-09): GIPHY through the API
-------------------------------------------------------------------------------------------------------
create table app.gif_settings (
  id              boolean primary key default true check (id),
  -- AES-256-GCM, base64(iv | tag | ciphertext), purpose-bound, with SETTINGS_ENCRYPTION_KEY (like the Waabek key).
  giphy_key_enc   text check (giphy_key_enc is null or length(giphy_key_enc) between 40 and 4000),
  updated_by      uuid references app.admin_accounts (id),
  updated_at      timestamptz
);
insert into app.gif_settings (id) values (true);
comment on table app.gif_settings is 'GIF search settings (O-09). One row. The GIPHY API key is stored only encrypted.';

-- A GIF copied into chat-media once; later sends of the same GIF reference the same file.
create table app.gif_files (
  giphy_id    text primary key check (giphy_id ~ '^[A-Za-z0-9]{1,64}$'),
  file_id     uuid not null unique references app.files (id),
  created_at  timestamptz not null default now()
);

-------------------------------------------------------------------------------------------------------
-- Messages: a file (media) or a sticker, with an optional caption for files
-------------------------------------------------------------------------------------------------------
alter table app.messages add column file_id uuid references app.files (id);
alter table app.messages add column sticker_id uuid references app.stickers (id);

alter table app.messages drop constraint messages_kind_check;
alter table app.messages add constraint messages_kind_check check (kind in ('text', 'media', 'sticker'));
alter table app.messages add constraint messages_kind_content check (
  (kind = 'media') = (file_id is not null)
  and (kind = 'sticker') = (sticker_id is not null)
  and (kind <> 'sticker' or text is null)
);
-- Until deleted for both sides a message has text, a file or a sticker; once deleted its text is gone (kept in
-- audit.message_revisions) while the file or sticker reference stays, locked (D-38).
alter table app.messages drop constraint messages_deleted_state;
alter table app.messages add constraint messages_content check (
  deleted_at is not null or text is not null or file_id is not null or sticker_id is not null
);
alter table app.messages add constraint messages_deleted_text check (deleted_at is null or text is null);

-- The chat's media panel (photos and videos, files, voice messages).
create index messages_files_idx on app.messages (conversation_id, seq) where file_id is not null;

-- Revisions record which file or sticker the message carried, so a caption-less photo can be edited (a caption
-- added) or deleted with a complete record.
alter table audit.message_revisions add column file_id uuid;
alter table audit.message_revisions add column sticker_id uuid;
alter table audit.message_revisions drop constraint message_revisions_previous_text;
alter table audit.message_revisions add constraint message_revisions_previous_text check (
  action = 'deleted_for_me' or previous_text is not null or file_id is not null or sticker_id is not null
);

-------------------------------------------------------------------------------------------------------
-- Reactions: one per person per message
-------------------------------------------------------------------------------------------------------
create table app.message_reactions (
  message_id       uuid not null references app.messages (id),
  conversation_id  uuid not null references app.conversations (id),
  user_id          uuid not null references app.users (id),
  emoji            text not null check (char_length(emoji) between 1 and 16),
  created_at       timestamptz not null default now(),
  primary key (message_id, user_id)
);
create index message_reactions_conversation_idx on app.message_reactions (conversation_id);

-------------------------------------------------------------------------------------------------------
-- Runtime privileges (bedo_runtime)
-------------------------------------------------------------------------------------------------------
-- Delete and update: only unused upload slots (the trigger refuses anything else).
grant select, insert, update, delete on app.files to bedo_runtime;
grant select, insert, update on app.sticker_packs, app.stickers to bedo_runtime;
grant select, update on app.gif_settings to bedo_runtime;
grant select, insert on app.gif_files to bedo_runtime;
grant select, insert, update, delete on app.message_reactions to bedo_runtime;

-------------------------------------------------------------------------------------------------------
-- Storage buckets (Supabase only)
-------------------------------------------------------------------------------------------------------
do $$
begin
  if to_regclass('storage.buckets') is not null then
    -- Private: every download is a short-lived signed URL given after a permission check. 50 MB per file (O-12).
    insert into storage.buckets (id, name, public, file_size_limit)
    values ('chat-media', 'chat-media', false, 52428800)
    on conflict (id) do nothing;
    -- Public: sticker images (no personal data), uploaded only by the API.
    insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    values ('stickers', 'stickers', true, 524288, array['image/png', 'image/webp'])
    on conflict (id) do nothing;
  end if;
end
$$;
-- End of the delivered migration file 20261010120000 ------------------------------------------------------------

-- Part 6: supabase/migrations/20261011120000_phase5_groups.sql, exactly as delivered ----------------------------
-- Bedo Chat - Phase 5: groups (D-39).
--
-- Groups are conversations of type 'group' in the same tables as private chats, so messages, media, pins, reactions,
-- search and sync work unchanged. Each member has a role (owner, admin, member); admins hold a set of admin rights;
-- every member's permissions are the group's defaults minus any restriction an admin placed on them. Member privacy
-- (O-04: two switches) hides the member count and/or the member list from normal members: the API decides through
-- one policy function, and the member list and count are read only through the functions below, which check the
-- caller's role themselves and refuse otherwise.
--
-- Also: invite links and join requests, polls (with quiz mode), mentions, mute (per user and chat), the system
-- permissions an admin manages per user (O-21: create groups, create channels, schedule messages), and the
-- permanent membership history (D-17).

-------------------------------------------------------------------------------------------------------
-- Conversations and members
-------------------------------------------------------------------------------------------------------
alter table app.conversations drop constraint conversations_type_check;
alter table app.conversations add constraint conversations_type_check check (type in ('private', 'group'));
alter table app.conversations add column title text check (title is null or char_length(title) between 1 and 128);
alter table app.conversations add column description text check (description is null or char_length(description) <= 255);
alter table app.conversations add column photo_key text check (photo_key is null or length(photo_key) <= 300);
-- A deleted group keeps its messages (history) but nobody can open it any more.
alter table app.conversations add column deleted_at timestamptz;
alter table app.conversations add constraint conversations_group_title check (type <> 'group' or title is not null);

alter table app.conversation_members add column role text not null default 'member' check (role in ('owner', 'admin', 'member'));
-- Admin rights (groups): only for admins; the owner holds every right.
alter table app.conversation_members add column admin_rights text[] not null default '{}' check (
  admin_rights <@ array['change_info', 'delete_messages', 'restrict_members', 'invite_users', 'approve_requests', 'pin_messages', 'manage_admins', 'change_privacy']::text[]
);
-- Restrictions (groups): permissions taken from this member until a time (null: until lifted).
alter table app.conversation_members add column denied_permissions text[] not null default '{}' check (
  denied_permissions <@ array['send_messages', 'send_media', 'send_stickers', 'send_polls', 'add_members', 'pin_messages', 'change_info']::text[]
);
alter table app.conversation_members add column restricted_until timestamptz;
alter table app.conversation_members add constraint conversation_members_admin_rights check (role = 'admin' or admin_rights = '{}');
create unique index conversation_members_one_owner on app.conversation_members (conversation_id) where role = 'owner';
create index conversation_members_staff_idx on app.conversation_members (conversation_id) where role in ('owner', 'admin');

create table app.group_settings (
  conversation_id      uuid primary key references app.conversations (id),
  -- What every member may do (an admin can restrict one member further).
  default_permissions  text[] not null default array['send_messages', 'send_media', 'send_stickers', 'send_polls', 'add_members', 'pin_messages']::text[] check (
    default_permissions <@ array['send_messages', 'send_media', 'send_stickers', 'send_polls', 'add_members', 'pin_messages', 'change_info']::text[]
  ),
  -- O-04: member privacy, two switches. Owners and admins always see both.
  hide_member_count    boolean not null default false,
  hide_member_list     boolean not null default false,
  updated_at           timestamptz not null default now()
);
create trigger group_settings_set_updated_at before update on app.group_settings
  for each row execute function app.set_updated_at();

